export const STARTER_TEMPLATES_CI_GITHUB_WORKFLOWS_SDD_INTEGRATE_ON_MERGE_YML = "name: SDD Canonical Integration on Merge\r\n\r\non:\r\n  pull_request:\r\n    types: [closed]\r\n    branches:\r\n      - main\r\n      - 'release/**'\r\n  workflow_dispatch:\r\n    inputs:\r\n      change_id:\r\n        description: 'SDD change ID to integrate manually (e.g. chg-001-telemetry)'\r\n        required: false\r\n        type: string\r\n\r\npermissions:\r\n  contents: write\r\n  pull-requests: read\r\n\r\nconcurrency:\r\n  group: sdd-integrate-${{ github.event.pull_request.base.ref || github.ref_name }}\r\n  cancel-in-progress: false\r\n\r\njobs:\r\n  integrate-sdd:\r\n    name: SDD Canonical Integration\r\n    if: github.event.pull_request.merged == true || github.event_name == 'workflow_dispatch'\r\n    runs-on: ubuntu-latest\r\n\r\n    steps:\r\n      - name: Checkout Repository\r\n        uses: actions/checkout@v4\r\n        with:\r\n          ref: ${{ github.event.pull_request.base.ref || github.ref_name }}\r\n          fetch-depth: 0\r\n          token: ${{ secrets.GITHUB_TOKEN }}\r\n\r\n      - name: Install pnpm\r\n        uses: pnpm/action-setup@v4\r\n        with:\r\n          version: 10\r\n\r\n      - name: Setup Node.js\r\n        uses: actions/setup-node@v4\r\n        with:\r\n          node-version: 20\r\n\r\n      - name: Install Dependencies\r\n        run: |\r\n          pnpm install --frozen-lockfile\r\n          pnpm approve-builds --all\r\n\r\n      - name: Build Packages\r\n        run: pnpm run build\r\n\r\n      - name: Detect and Integrate SDD Change\r\n        id: integrate\r\n        env:\r\n          PR_HEAD_REF: ${{ github.event.pull_request.head.ref }}\r\n          PR_TITLE: ${{ github.event.pull_request.title }}\r\n          PR_BODY: ${{ github.event.pull_request.body }}\r\n          MANUAL_CHANGE_ID: ${{ github.event.inputs.change_id }}\r\n        run: |\r\n          npx @aisdlc/cli sdd integrate --auto || true\r\n\r\n      - name: Commit and Push Canonical Baseline Changes\r\n        run: |\r\n          git config user.name \"github-actions[bot]\"\r\n          git config user.email \"github-actions[bot]@users.noreply.github.com\"\r\n          git add -A\r\n          if ! git diff --cached --quiet; then\r\n            git commit -m \"chore(sdd): integrate changes into canonical baseline [skip ci]\"\r\n            TARGET_BRANCH=\"${{ github.event.pull_request.base.ref || github.ref_name }}\"\r\n            MAX_RETRIES=3\r\n            RETRY_COUNT=0\r\n            DELAY=2\r\n\r\n            while [ $RETRY_COUNT -lt $MAX_RETRIES ]; do\r\n              echo \"Synchronizing with remote branch $TARGET_BRANCH (pull --rebase)...\"\r\n              git pull --rebase origin \"$TARGET_BRANCH\"\r\n              if git push origin \"$TARGET_BRANCH\"; then\r\n                echo \"✔ Canonical integration committed and synchronized to repository.\"\r\n                exit 0\r\n              fi\r\n              RETRY_COUNT=$((RETRY_COUNT + 1))\r\n              if [ $RETRY_COUNT -lt $MAX_RETRIES ]; then\r\n                echo \"⚠ Push rejected (concurrency detected). Retrying in ${DELAY}s (attempt $RETRY_COUNT/$MAX_RETRIES)...\"\r\n                sleep $DELAY\r\n                DELAY=$((DELAY * 2))\r\n              fi\r\n            done\r\n\r\n            echo \"❌ Error: Failed to push canonical integration after $MAX_RETRIES attempts.\"\r\n            exit 1\r\n          else\r\n            echo \"ℹ No pending changes generated in working tree.\"\r\n          fi\r\n";

